  "circles.stmt.preparing": { en: "Preparing…", pidgin: "E dey prepare…", ha: "Ana shiryawa…", ig: "A na-akwado…", yo: "À ń pèsè rẹ̀…" },
  "circles.stmt.exporting": { en: "Exporting…", pidgin: "E dey export…", ha: "Ana fitarwa…", ig: "A na-ebupụ…", yo: "À ń gbé e jáde…" },
  "circles.stmt.opening":   { en: "Opening balance", pidgin: "Opening balance", ha: "Ma'auni na farko", ig: "Ego mmalite", yo: "Ìwọ̀ntúnwọ̀nsì ìbẹ̀rẹ̀" },
  "circles.stmt.closing":   { en: "Closing balance", pidgin: "Closing balance", ha: "Ma'auni na ƙarshe", ig: "Ego ngwụcha", yo: "Ìwọ̀ntúnwọ̀nsì ìparí" },
